class Solution:
    def searchInsert(self, nums: List[int], target: int) -> int:
        lo, hi = 0, len(nums) - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if nums[mid] == target:
                return mid
            elif nums[mid] < target:
                lo = mid + 1          # 目标在右半
            else:
                hi = mid - 1          # 目标在左半
        return lo                     # lo = 第一个 >= target 的下标

class Solution:
    def searchMatrix(self, matrix: List[List[int]], target: int) -> bool:
        m, n = len(matrix), len(matrix[0])
        lo, hi = 0, m * n - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            val = matrix[mid // n][mid % n]   # 一维下标 → 行列
            if val == target:
                return True
            elif val < target:
                lo = mid + 1
            else:
                hi = mid - 1
        return False

class Solution:
    def searchRange(self, nums: List[int], target: int) -> List[int]:
        def lower_bound(t):            # 第一个 >= t 的下标
            lo, hi = 0, len(nums)
            while lo < hi:
                mid = (lo + hi) // 2
                if nums[mid] >= t:
                    hi = mid           # mid 可能是答案，保留
                else:
                    lo = mid + 1
            return lo

        left = lower_bound(target)
        if left == len(nums) or nums[left] != target:
            return [-1, -1]
        return [left, lower_bound(target + 1) - 1]

class Solution:
    def search(self, nums: List[int], target: int) -> int:
        lo, hi = 0, len(nums) - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if nums[mid] == target:
                return mid
            if nums[lo] <= nums[mid]:            # 左半 [lo..mid] 有序
                if nums[lo] <= target < nums[mid]:
                    hi = mid - 1                 # target 落在有序左半
                else:
                    lo = mid + 1
            else:                                # 右半 [mid..hi] 有序
                if nums[mid] < target <= nums[hi]:
                    lo = mid + 1
                else:
                    hi = mid - 1
        return -1

class Solution:
    def findMin(self, nums: List[int]) -> int:
        lo, hi = 0, len(nums) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] > nums[hi]:   # 断崖在 mid 右侧
                lo = mid + 1
            else:                      # 最小值在 mid 及左侧
                hi = mid
        return nums[lo]

class Solution:
    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:
        if len(nums1) > len(nums2):          # 保证在较短的数组上二分
            nums1, nums2 = nums2, nums1
        m, n = len(nums1), len(nums2)
        half = (m + n + 1) // 2              # 左半部分应取的元素个数
        lo, hi = 0, m
        while lo <= hi:
            i = (lo + hi) // 2               # nums1 左部取 i 个
            j = half - i                     # nums2 左部取 j 个
            L1 = nums1[i - 1] if i else float("-inf")
            R1 = nums1[i] if i < m else float("inf")
            L2 = nums2[j - 1] if j else float("-inf")
            R2 = nums2[j] if j < n else float("inf")
            if L1 <= R2 and L2 <= R1:        # 分割线合法
                if (m + n) % 2:
                    return float(max(L1, L2))
                return (max(L1, L2) + min(R1, R2)) / 2
            elif L1 > R2:
                hi = i - 1                   # nums1 左部太多
            else:
                lo = i + 1
        raise ValueError("unreachable")
